-- ============================================================
-- SEED EXT 3: Módulo 06 — Be Going To (ex 108-205)
-- Novos tópicos: was going to (passado), future in the past,
-- revisão de todos futuros, futuros acadêmicos, TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'be-going-to';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo be-going-to não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 31: was going to — unrealized past plans
  (cid,31,108,'gap_fill','She _____ (be going to / present) her research at the conference, but the event was cancelled.','was going to present',NULL,'"Was going to + base verb" = unrealized past plan/intention.','medium'),
  (cid,31,109,'multiple_choice','What does "was going to" express?','A past intention or plan that was not carried out.','["A completed past action","A past intention or plan that was not carried out.","A prediction based on past evidence","A past habit"]','"Was/were going to + base verb" = unrealized past intention.','medium'),
  (cid,31,110,'gap_fill','The government _____ (be going to / implement) the carbon tax last year, but political opposition delayed it.','was going to implement',NULL,'"Was going to implement" = policy intention that didn''t materialize.','medium'),
  (cid,31,111,'multiple_choice','Which sentence uses "was going to" correctly?','He was going to submit the paper in April but needed more time to revise.','["He was going to submit the paper in April and did so.","He is going to submit the paper in April but needs more time.","He was going to submit the paper in April but needed more time to revise.","He will going to submit the paper in April."]','"Was going to + base verb + but + past simple (interruption/change)" = classic unrealized plan pattern.','medium'),
  (cid,31,112,'gap_fill','The team _____ (be going to / announce) the results at the press conference, but a data error was discovered at the last minute.','were going to announce',NULL,'"Were going to announce" for a group plan that was aborted.','medium'),

  -- BLOCK 32: future in the past — would/was about to/was due to
  (cid,32,113,'gap_fill','The experiment _____ (be about to / begin) when the fire alarm sounded.','was about to begin',NULL,'"Was about to + base verb" = on the verge of (immediate future in the past).','hard'),
  (cid,32,114,'multiple_choice','Which expresses "future in the past" most naturally?','The treaty, which was due to be signed in January, was ultimately delayed until March.','["The treaty, which will be signed in January, was delayed until March.","The treaty, which was due to be signed in January, was ultimately delayed until March.","The treaty, which is about to be signed in January, was delayed until March.","The treaty, which would sign in January, was delayed until March."]','"Was due to be signed" = formal scheduled future in the past (passive).','hard'),
  (cid,32,115,'gap_fill','Little did we know that this small discovery _____ (would / change) the entire course of the investigation.','would change',NULL,'"Would + base verb" = future in the past (retrospective narrative).','hard'),
  (cid,32,116,'multiple_choice','In the sentence "In 1969, no one could have known that the Internet would become the dominant communication medium of the 21st century," "would become" is:','A future in the past — what the future would bring, viewed from a past perspective.','["A conditional result clause (Type 3)","A future in the past — what the future would bring, viewed from a past perspective.","A past habitual action","An uncertain prediction"]','"Would become" = future from the perspective of 1969 (future in the past).','hard'),
  (cid,32,117,'gap_fill','The initial reports _____ (prove) misleading — investigators _____ (would / spend) months unraveling the true sequence of events.','proved / would spend',NULL,'Past simple narrative + would for subsequent future-in-past.','hard'),

  -- BLOCK 33: going to vs will — revisão avançada
  (cid,33,118,'multiple_choice','Which best fits? A doctor looks at test results and says: "___ you need surgery."','You are going to need','["You will need surgery (also possible — prediction).","You are going to need (based on visible evidence — going to).","You need surgery (present simple — blunt).","You are needing surgery (wrong — stative verb)."]','Evidence-based prediction (test results visible) → "going to." Will = less immediate.','hard'),
  (cid,33,119,'gap_fill','A: "I don''t have any cash." B: "It''s OK, I _____ (pay) for you." (spontaneous decision)','will pay',NULL,'"Will + base verb" = spontaneous decision at the moment of speaking. NOT going to (which implies prior plan).','medium'),
  (cid,33,120,'multiple_choice','Which future form is MOST appropriate? "I''ve bought the ingredients — I _____ pasta for dinner."','am going to make','["will make (decision just made — less accurate since ingredients bought)","am going to make (prior plan — ingredients already purchased).","make (present simple — wrong for this personal plan).","am making (also correct for personal arrangement)."]','"Going to" = prior plan (evidence: bought ingredients). "Am making" also possible for personal arrangement.','hard'),
  (cid,33,121,'gap_fill','The weather forecast says it _____ (snow) tomorrow. You should leave early. (reported prediction based on evidence)','is going to snow',NULL,'"Going to" for prediction based on evidence (forecast = visible evidence of future).','easy'),
  (cid,33,122,'multiple_choice','Which sentence INCORRECTLY uses going to?','I''m going to call you as soon as I arrive. (should use will in the if/as soon as clause)','["I''m going to quit my job if they don''t give me a raise.","I''m going to call you as soon as I arrive. (should use will in the if/as soon as clause)","Look! That vase is going to fall!","We''re going to implement the policy next quarter."]','In future time clauses (as soon as/when/before), present simple is used — not going to. Main clause can use going to.','hard'),

  -- BLOCK 34: going to com passivo
  (cid,34,123,'gap_fill','The old hospital _____ (demolish/passive + going to) and replaced with a new medical center.','is going to be demolished',NULL,'"Is going to be + past participle" = going to passive.','hard'),
  (cid,34,124,'multiple_choice','Which is the CORRECT passive going to form?','The data are going to be analyzed by an independent team.','["The data going to be analyzed by an independent team.","The data is going to analyze by an independent team.","The data are going to be analyzed by an independent team.","The data are going to analyzed by an independent team."]','"Are going to be + past participle" = future passive with going to.','hard'),
  (cid,34,125,'gap_fill','The new legislation _____ (present/passive + going to) to parliament next month.','is going to be presented',NULL,'"Is going to be presented" = planned passive future event.','hard'),

  -- BLOCK 35: TOEFL Reading
  (cid,35,126,'multiple_choice','[TOEFL Reading] "By the early 20th century, scientists who studied atomic structure were going to uncover findings that would overturn classical physics." What does "were going to uncover" express?','A future in the past — what was ahead for those scientists from an early 20th century perspective.','["A completed past action","A future in the past — what was ahead for those scientists from an early 20th century perspective.","A conditional outcome","A current prediction"]','"Were going to uncover" = future from a past perspective (historical narrative).','medium'),
  (cid,35,127,'gap_fill','[TOEFL Reading] "The construction was due to _____ (begin) in March, but permit delays pushed the start date back to September." Best form?','begin',NULL,'"Was due to + base verb" = formally scheduled future in the past.','medium'),
  (cid,35,128,'multiple_choice','[TOEFL Reading] "Researchers were about to publish their findings when a competing team announced a similar discovery." "Were about to" means:','They were on the verge of publishing — the event was imminent.','["They had already published","They had no intention of publishing","They were on the verge of publishing — the event was imminent.","They published after the competing announcement"]','"Were about to + base verb" = on the immediate verge of action.','easy'),
  (cid,35,129,'gap_fill','[TOEFL Reading] "The industrial plant, which _____ (be going to / close) in 2015, received an emergency loan and continued operating." Best form?','was going to close',NULL,'"Was going to close" = planned future event that was prevented.','medium'),

  -- BLOCK 36: TOEFL Speaking
  (cid,36,130,'production','[TOEFL Speaking — 45s] A reading says that self-driving cars are going to transform cities within 10 years. Discuss using: is going to, was going to (past policy that failed), would (future in past), will be, is about to.','',NULL,'Self-driving vehicles are going to fundamentally reshape urban design by reducing the need for parking and enabling more fluid traffic patterns. Several city governments were going to introduce autonomous vehicle zones last year, but public safety concerns caused delays. Historically, planners predicted that electric vehicles would become mainstream far sooner than they actually did, which suggests we should be cautious about timelines. That said, the technology is about to cross critical reliability thresholds, and large-scale deployment will be underway within this decade.','hard'),
  (cid,36,131,'production','[TOEFL Speaking — 45s] Disagree with this claim: "Young people today are not going to face more challenges than previous generations." Use: going to, was going to (unrealized past), would (future in past), will.','',NULL,'I disagree strongly. Young people today are going to face a unique convergence of challenges — climate instability, economic precarity, and technological disruption — that earlier generations did not experience simultaneously. Previous generations were going to benefit from social safety nets that are now eroding. No one in 1980 imagined that housing would become unaffordable for the majority of young adults in major cities. The challenges ahead are real, and we should not minimize them.','hard'),

  -- BLOCK 37: TOEFL Writing
  (cid,37,132,'production','[TOEFL Writing — 150 words] Write an academic paragraph on "The future of healthcare." Use: is going to, will, future perfect (will have), future in the past (would), was going to, is due to.','',NULL,'Healthcare is going to be transformed by the convergence of artificial intelligence, genomics, and personalized medicine. Several policies that governments were going to implement in the early 2000s — including universal electronic health records — were delayed by political resistance and data security concerns. Those who imagined that healthcare would become fully digitized by 2010 underestimated the complexity of the transition. However, by 2040, most diagnostic processes will have been substantially automated, freeing clinicians to focus on patient relationships and complex decision-making. A new framework for healthcare regulation is due to be introduced by the WHO in the coming years, which will establish global standards for AI-assisted diagnosis. The combination of earlier detection, more targeted treatments, and preventive medicine means that average life expectancy will likely continue to extend significantly.','hard'),
  (cid,37,133,'production','[TOEFL Writing — Error Correction] Fix future/going-to errors: "She was going to presented her findings but fell ill. The building is going to demolished next year. Little did they know that the discovery will change everything. The report is going to be presented at March."','',NULL,'was going to presented → was going to present (base verb after going to, no past participle); is going to demolished → is going to be demolished (passive = be + past participle); will change → would change (future in the past narrative); at March → in March (month = in).','hard'),
  (cid,37,134,'production','[TOEFL Writing — 200 words] Write a TOEFL-style paragraph on "Should governments use going to predictions or will predictions in official policy documents?" (This is a meta-question about language and governance.) Alternatively: write about "Urban planning for the future" using all 6 future forms at least once: present simple (schedule), going to, will, future continuous, future perfect, future in the past (would).','',NULL,'A new master plan for the city of Bogotá is scheduled to take effect in 2026, outlining how the metropolitan region is going to manage a projected 25% population increase over the next two decades. Planners predict that 60% of all commutes will be made by public transport by 2040, reducing car dependency significantly. By the time the new metro lines are fully operational, engineers will have been designing and building the system for over fifteen years. During peak construction phases, tens of thousands of workers will be employed across dozens of active sites simultaneously. Few urban planners in the 1990s imagined that Bogotá would become an international model for sustainable urban transformation. The city''s transformation demonstrates that bold, long-term planning combined with political will and public investment can fundamentally change the character and livability of a major metropolis.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
